'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var Float64Array = require( '@stdlib/array/float64' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dlaln2 = require( './../lib/ndarray.js' );


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];
var SIZES = [
	[ 1, 1 ],
	[ 1, 2 ],
	[ 2, 1 ],
	[ 2, 2 ]
];
var opts = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {PositiveInteger} NA - size of the matrix `A`
* @param {PositiveInteger} NW - `1` if `w` is real and `2` if `w` is complex
* @returns {Function} benchmark function
*/
function createBenchmark( order, NA, NW ) {
	var out;
	var sa1;
	var sa2;
	var sb1;
	var sb2;
	var A;
	var B;
	var X;

	out = new Float64Array( 2 );
	A = uniform( NA*NA, 1.0, 10.0, opts );
	B = uniform( NA*NW, 1.0, 10.0, opts );
	X = new Float64Array( NA*NW );
	if ( order === 'row-major' ) {
		sa1 = NA;
		sa2 = 1;
		sb1 = NW;
		sb2 = 1;
	} else {
		sa1 = 1;
		sa2 = NA;
		sb1 = 1;
		sb2 = NA;
	}
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var i;
		var z;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = dlaln2( 'no-transpose', NA, NW, 1.0e-3, 1.0, A, sa1, sa2, 0, 1.0, 1.0, B, sb1, sb2, 0, 0.5, 0.5, X, sb1, sb2, 0, out, 1, 0 );
			if ( isnan( z ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( out[ 1 ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var ord;
	var NA;
	var NW;
	var f;
	var i;
	var j;

	for ( j = 0; j < LAYOUTS.length; j++ ) {
		ord = LAYOUTS[ j ];
		for ( i = 0; i < SIZES.length; i++ ) {
			NA = SIZES[ i ][ 0 ];
			NW = SIZES[ i ][ 1 ];
			f = createBenchmark( ord, NA, NW );
			bench( format( '%s:ndarray:order=%s,NA=%d,NW=%d', pkg, ord, NA, NW ), f );
		}
	}
}

main();
